import{_ as E,H as c,o as e,c as g,aN as s,q as i,s as a,a as o,l as n,aT as r,j as d}from"./chunks/framework.D31DlcCL.js";const h="/img/badminton/zhengshou-cuoqiu-prepare.jpg",B="/img/badminton/zhengshou-cuoqiu-backswing.jpg",m="/img/badminton/zhengshou-cuoqiu-contact.jpg",u="/img/badminton/zhengshou-cuoqiu-followthrough.jpg",x=JSON.parse('{"title":"正手搓球_笔记","description":"这是一个关于正手搓球的笔记，介绍了网前正手搓球的基础技术。","frontmatter":{"title":"正手搓球_笔记","date":"2026-03-10T10:25:00.000Z","categories":["体育与健康"],"tags":["体育","羽毛球","搓球"],"description":"这是一个关于正手搓球的笔记，介绍了网前正手搓球的基础技术。","cover":"/img/badminton/zhengshou-cuoqiu-cover.jpg","top_img":"/img/badminton/zhengshou-cuoqiu-top.jpg","toc_number":true},"headers":[],"relativePath":"posts/badminton-zhengshou-cuoqiu.md","filePath":"posts/badminton-zhengshou-cuoqiu.md","lastUpdated":null}'),p={name:"posts/badminton-zhengshou-cuoqiu.md"};function A(f,t,b,_,k,D){const l=c("Mermaid");return e(),g("div",null,[t[2]||(t[2]=s('<h1 id="羽毛球-正手搓球" tabindex="-1">羽毛球 - 正手搓球 <a class="header-anchor" href="#羽毛球-正手搓球" aria-label="Permalink to &quot;羽毛球 - 正手搓球&quot;">​</a></h1><h2 id="一、技术概述" tabindex="-1">一、技术概述 <a class="header-anchor" href="#一、技术概述" aria-label="Permalink to &quot;一、技术概述&quot;">​</a></h2><p>正手搓球是网前进攻的核心技术之一。通过精细的指尖控制，使球在网前翻滚，迫使对手回出被动球，从而创造得分机会。</p><h2 id="二、动作分解图示" tabindex="-1">二、动作分解图示 <a class="header-anchor" href="#二、动作分解图示" aria-label="Permalink to &quot;二、动作分解图示&quot;">​</a></h2>',4)),(e(),i(r,null,{default:a(()=>[n(l,{id:"mermaid-12",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20classDef%20net%20fill%3A%23e1f5fe%2Cstroke%3A%2301579b%3B%0A%20%20%20%20classDef%20action%20fill%3A%23fff3e0%2Cstroke%3A%23e65100%3B%0A%20%20%20%20classDef%20finish%20fill%3A%23f3e5f5%2Cstroke%3A%234a148c%3B%0A%0A%20%20%20%20A%5B%E5%87%86%E5%A4%87%3A%20%E8%B7%A8%E6%AD%A5%E4%B8%8A%E7%BD%91%2F%E6%8B%8D%E9%9D%A2%E5%B9%B3%E4%B8%BE%5D%20--%3E%20B%5B%E5%BC%95%E6%8B%8D%3A%20%E6%9E%81%E5%B0%8F%E5%90%8E%E6%92%A4%2F%E6%89%8B%E6%8C%87%E6%94%BE%E6%9D%BE%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%88%87%E6%90%93%3A%20%E6%89%8B%E6%8C%87%E6%8D%BB%E5%8A%A8%2F%E5%88%87%E5%87%BB%E7%90%83%E6%89%98%5D%0A%20%20%20%20C%20--%3E%20D%5B%E5%87%BB%E7%90%83%3A%20%E6%9F%94%E5%92%8C%E5%88%87%E6%90%93%2F%E4%BA%A7%E7%94%9F%E7%BF%BB%E6%BB%9A%5D%0A%20%20%20%20D%20--%3E%20E%5B%E9%9A%8F%E5%89%8D%3A%20%E6%8B%8D%E9%9D%A2%E5%BE%AE%E6%94%B6%2F%E5%BF%AB%E9%80%9F%E5%9B%9E%E4%BD%8D%5D%0A%0A%20%20%20%20class%20A%20net%3B%0A%20%20%20%20class%20B%20net%3B%0A%20%20%20%20class%20C%20action%3B%0A%20%20%20%20class%20D%20action%3B%0A%20%20%20%20class%20E%20finish%3B%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=d("h3",{id:"身体姿态可视化图解",tabindex:"-1"},[o("身体姿态可视化图解 "),d("a",{class:"header-anchor",href:"#身体姿态可视化图解","aria-label":'Permalink to "身体姿态可视化图解"'},"​")],-1)),(e(),i(r,null,{default:a(()=>[n(l,{id:"mermaid-16",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20%22%E7%BD%91%E5%89%8D%E6%90%93%E7%90%83%E5%A7%BF%E6%80%81%20(%E4%BF%AF%E8%A7%86%E5%9B%BE%E8%A7%86%E8%A7%92)%22%0A%20%20%20%20RK%5B%E7%90%83%E6%8B%8D%3A%20%E6%B0%B4%E5%B9%B3%E5%88%87%E5%90%91%E7%90%83%E6%89%98%E4%BE%A7%E4%B8%8B%E6%96%B9%5D%20---%20Ball((%E7%BE%BD%E6%AF%9B%E7%90%83%3A%20%E7%BF%BB%E6%BB%9A%E8%BF%87%E7%BD%91))%0A%20%20%20%20RK%20---%20Wrist(%E6%89%8B%E8%85%95%3A%20%E9%94%81%E6%AD%BB%E5%9B%BA%E5%AE%9A)%0A%20%20%20%20Wrist%20---%20Fingers(%E6%89%8B%E6%8C%87%3A%20%E9%A3%9F%E6%8C%87%E6%8B%87%E6%8C%87%E6%8D%BB%E5%8A%A8)%0A%20%20%20%20Fingers%20---%20Arm(%E6%89%8B%E8%87%82%3A%20%E8%87%AA%E7%84%B6%E5%90%91%E5%89%8D%E4%BC%B8%E5%B1%95)%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[o(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=s('<h2 id="三、详细动作分解" tabindex="-1">三、详细动作分解 <a class="header-anchor" href="#三、详细动作分解" aria-label="Permalink to &quot;三、详细动作分解&quot;">​</a></h2><h3 id="_1-准备阶段-preparation" tabindex="-1">1. 准备阶段 (Preparation) <a class="header-anchor" href="#_1-准备阶段-preparation" aria-label="Permalink to &quot;1. 准备阶段 (Preparation)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">画面要求</p><p>真人向右前方跨步，右脚在前，重心平稳。球拍平举在身体前上方，拍面几乎与网沿平齐，展现出高度的专注。</p></div><p><img src="'+h+'" alt="动作示范：网前准备搓球姿势"><em>图1：跨步上网，重心稳定，持拍手自然伸出，拍面水平</em></p><ul><li><strong>跨步上网</strong>：右脚大幅跨步上网，确保身体重心前移并保持稳定。</li><li><strong>拍面平举</strong>：持拍手自然伸向网前，拍面基本与地面平行或略向上仰。</li></ul><h3 id="_2-引拍阶段-backswing" tabindex="-1">2. 引拍阶段 (Backswing) <a class="header-anchor" href="#_2-引拍阶段-backswing" aria-label="Permalink to &quot;2. 引拍阶段 (Backswing)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">画面要求</p><p>特写镜头。手腕几乎不动，仅仅是手指（食指和拇指）轻微向后方松开一点点，展现出极小的动作幅度。</p></div><p><img src="'+B+'" alt="动作图解：极小幅度引拍"><em>图2：手腕微向后张，手指处于极度放松状态</em></p><ul><li><strong>极小引拍</strong>：搓球不需要大幅度挥拍，只需手腕微向后张，重点在于手指的放松状态。</li><li><strong>目光锁定</strong>：紧盯球托，判断来球的速度和旋转。</li></ul><h3 id="_3-切搓与击球-swing-contact" tabindex="-1">3. 切搓与击球 (Swing &amp; Contact) <a class="header-anchor" href="#_3-切搓与击球-swing-contact" aria-label="Permalink to &quot;3. 切搓与击球 (Swing &amp; Contact)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">画面要求</p><p>捕捉手指捻动的瞬间。球拍边缘轻微摩擦羽毛球托侧部，球在空中呈现出翻转的动态，展现出极其柔和的手感。</p></div><p><img src="'+m+'" alt="动作示范：切搓球托瞬间"><em>图3：通过手指捻动，使拍面轻柔切击球托侧下方，产生翻滚</em></p><ul><li><strong>手指发力</strong>：这是核心。通过食指和拇指的微小“捻动”，带动拍面切击球托的侧下方。</li><li><strong>击球轨迹</strong>：拍面斜向前上方切出，力量要柔和，类似“削”皮的动作。</li><li><strong>产生翻滚</strong>：通过摩擦球托使羽毛球产生不规则翻滚，让球紧贴球网落下。</li></ul><h3 id="_4-随前动作-follow-through" tabindex="-1">4. 随前动作 (Follow-through) <a class="header-anchor" href="#_4-随前动作-follow-through" aria-label="Permalink to &quot;4. 随前动作 (Follow-through)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">画面要求</p><p>动作收尾。球拍保持在击球点位置稍微停顿，观察球翻滚过网后，身体迅速向后小步撤回。</p></div><p><img src="'+u+'" alt="动作图解：搓球后的自然停顿"><em>图4：击球后拍面保持不动，观察球的走向后迅速回中</em></p><h2 id="四、动作示范要领" tabindex="-1">四、动作示范要领 <a class="header-anchor" href="#四、动作示范要领" aria-label="Permalink to &quot;四、动作示范要领&quot;">​</a></h2><blockquote><p><strong>教学心得</strong>：搓球比的是“手感”。想象你手里握着一个生鸡蛋，既要握住又不能捏碎。击球时不是“打”球，而是“抚摸”球，让它在你的拍面上听话地滚过去。</p></blockquote><h2 id="五、易错点讲解-common-mistakes" tabindex="-1">五、易错点讲解 (Common Mistakes) <a class="header-anchor" href="#五、易错点讲解-common-mistakes" aria-label="Permalink to &quot;五、易错点讲解 (Common Mistakes)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">错误动作</th><th style="text-align:left;">产生后果</th><th style="text-align:left;">纠正方法</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>手腕发力过猛</strong></td><td style="text-align:left;">球飞得过高或过远，容易被扑死</td><td style="text-align:left;">锁死手腕，仅利用手指的捻动发力</td></tr><tr><td style="text-align:left;"><strong>击球点过低</strong></td><td style="text-align:left;">无法切搓，只能向上挑球</td><td style="text-align:left;">跨步要大，尽量在高点拦截来球</td></tr><tr><td style="text-align:left;"><strong>身体太僵硬</strong></td><td style="text-align:left;">缺乏灵活性，手感全无</td><td style="text-align:left;">膝盖微屈，保持重心的弹性</td></tr><tr><td style="text-align:left;"><strong>握拍太紧</strong></td><td style="text-align:left;">手指无法捻动，拍面僵硬</td><td style="text-align:left;">保持掌心空灵，击球瞬间才轻微加力</td></tr><tr><td style="text-align:left;"><strong>切击角度不对</strong></td><td style="text-align:left;">球不翻滚，直接平飞过网</td><td style="text-align:left;">调整拍面仰角，练习切击球托侧底部的感觉</td></tr></tbody></table><h3 id="易错点图示说明" tabindex="-1">易错点图示说明 <a class="header-anchor" href="#易错点图示说明" aria-label="Permalink to &quot;易错点图示说明&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">错误示范配图要求</p><ol><li><strong>手腕过大</strong>：<a href="/img/badminton/mistake-cuoqiu-wrist.jpg">图片占位：搓球手腕动作过大错误图</a> - 画面显示手腕有明显的摆动动作，导致球飞得很高。</li></ol></div>',22))])}const C=E(p,[["render",A]]);export{x as __pageData,C as default};
